package net.ye6isu.yebisuRPG.item.custom;

import net.minecraft.network.chat.Component;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.TooltipFlag;

import javax.annotation.Nullable;
import java.util.List;

/**
 * A simple Item subclass that supports normal and shift-reveal tooltips
 * driven entirely by lang keys — no anonymous class needed.
 *
 * Usage in ModItems.java (generated by Content Studio):
 *   new TooltipItem(new Item.Properties(),
 *       "tooltip.yebisurpg.myitem.normal",   // null = no normal tooltip
 *       "tooltip.yebisurpg.myitem.hidden",   // null = no hidden tooltip
 *       "tooltip.yebisurpg.shift_to_see")    // null = no shift hint
 */
public class TooltipItem extends Item {

    @Nullable private final String normalKey;
    @Nullable private final String hiddenKey;
    @Nullable private final String shiftHintKey;

    public TooltipItem(Properties properties,
                       @Nullable String normalKey,
                       @Nullable String hiddenKey,
                       @Nullable String shiftHintKey) {
        super(properties);
        this.normalKey   = normalKey;
        this.hiddenKey   = hiddenKey;
        this.shiftHintKey = shiftHintKey;
    }

    @Override
    public void appendHoverText(ItemStack stack, TooltipContext context,
                                List<Component> tooltip, TooltipFlag flag) {
        if (normalKey != null) {
            tooltip.add(Component.translatable(normalKey));
        }
        if (hiddenKey != null) {
            if (flag.isAdvanced() || net.minecraft.client.gui.screens.Screen.hasShiftDown()) {
                tooltip.add(Component.translatable(hiddenKey));
            } else if (shiftHintKey != null) {
                tooltip.add(Component.translatable(shiftHintKey));
            }
        }
        super.appendHoverText(stack, context, tooltip, flag);
    }
}
